create extension if not exists pgcrypto;
create schema if not exists app;
revoke all on schema app from public;

create table app.instagram_accounts (id uuid primary key default gen_random_uuid(), instagram_user_id text unique not null, username text, profile_picture_url text, access_token_ciphertext text, token_expires_at timestamptz, connection_status text not null default 'disconnected' check (connection_status in ('disconnected','connected','expired','error')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table app.automations (id uuid primary key default gen_random_uuid(), account_id uuid not null references app.instagram_accounts(id) on delete cascade, name text not null, active boolean not null default false, triggers text[] not null default '{}', keywords text[] not null default '{}', match_type text not null check (match_type in ('contains','exact','any')), media_id text, public_reply_variations text[] not null default '{}', welcome_message text, quick_reply_label text, cta_label text, cta_url text, reminder_message text, reminder_delay_minutes integer check (reminder_delay_minutes is null or reminder_delay_minutes >= 1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table app.followups (id uuid primary key default gen_random_uuid(), automation_id uuid not null references app.automations(id) on delete cascade, position smallint not null, content text not null, delay_minutes integer not null check (delay_minutes >= 0), active boolean not null default true, unique(automation_id, position));
create table app.contacts (id uuid primary key default gen_random_uuid(), account_id uuid not null references app.instagram_accounts(id) on delete cascade, instagram_scoped_id text not null, username text, first_contact_at timestamptz not null default now(), last_interaction_at timestamptz, conversation_window_opens_at timestamptz, last_automation_id uuid references app.automations(id) on delete set null, unique(account_id, instagram_scoped_id));
create table app.events (id uuid primary key default gen_random_uuid(), account_id uuid references app.instagram_accounts(id) on delete set null, provider_event_id text, event_type text not null, payload jsonb not null default '{}'::jsonb, processing_status text not null default 'received', received_at timestamptz not null default now(), processed_at timestamptz, unique(account_id, provider_event_id));
create table app.queue (id uuid primary key default gen_random_uuid(), account_id uuid not null references app.instagram_accounts(id) on delete cascade, contact_id uuid references app.contacts(id) on delete set null, automation_id uuid references app.automations(id) on delete set null, event_id uuid references app.events(id) on delete set null, delivery_type text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'pending' check (status in ('pending','sending','sent','failed','skipped')), attempts integer not null default 0, last_error text, claimed_at timestamptz, scheduled_at timestamptz not null default now(), sent_at timestamptz, idempotency_key text not null unique, created_at timestamptz not null default now());
create table app.audit_logs (id uuid primary key default gen_random_uuid(), action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table app.instagram_accounts enable row level security; alter table app.automations enable row level security; alter table app.followups enable row level security; alter table app.contacts enable row level security; alter table app.events enable row level security; alter table app.queue enable row level security; alter table app.audit_logs enable row level security;
create index queue_ready_index on app.queue (scheduled_at) where status = 'pending';
create index events_received_index on app.events (received_at desc);